export async function createScene(engine, canvas, BABYLON) {
  console.clear();

  var scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.82, 0.83, 0.75);
  scene.useRightHandedSystem = true;

  var box = BABYLON.MeshBuilder.CreateBox(
    "box",
    {
      width: Math.random() * 9 + 1, // 1 ~ 10
      height: Math.random() * 9 + 1,
      depth: Math.random() * 9 + 1,
    },
    scene
  );
  box.visibility = 0.5;
  box.showBoundingBox = true;

  var camera = new BABYLON.ArcRotateCamera("camera1", 1.22, BABYLON.Tools.ToRadians(60), 15, box.position, scene);
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", camera.position, scene);
  light.intensity = 0.7;

  function setBoundingText(mesh) {
    var meshPosCenter = mesh.getBoundingInfo().boundingBox.centerWorld;
    var meshSize = mesh.getBoundingInfo().boundingBox.extendSizeWorld;

    var bbv = mesh.getBoundingInfo().boundingBox.vectorsWorld;

    /**
     *          3+---------+5
     *          /|        /|
     *         / |       / |
     *       6+--+------+1 |
     *        |  |      |  |
     *        | 0+------|--+2
     *        | /       | /
     *        |/        |/
     *       4+---------+7
     */
    var xLine = [bbv[4], bbv[7]];
    var yLine = [bbv[4], bbv[6]];
    var zLine = [bbv[4], bbv[0]];

    let scaleFactor = 1.05;
    let xAxisLine = BABYLON.MeshBuilder.CreateLines("xLine", { points: xLine }, scene);
    xAxisLine.color = new BABYLON.Color3(1, 0, 0); // Red
    xAxisLine.scaling.scaleInPlace(scaleFactor);

    let yAxisLine = BABYLON.MeshBuilder.CreateLines("yLine", { points: yLine }, scene);
    yAxisLine.color = new BABYLON.Color3(0, 1, 0); // Green
    yAxisLine.scaling.scaleInPlace(scaleFactor);

    let zAxisLine = BABYLON.MeshBuilder.CreateLines("zLine", { points: zLine }, scene);
    zAxisLine.color = new BABYLON.Color3(0, 0, 1); // Blue
    zAxisLine.scaling.scaleInPlace(scaleFactor);

    var deg = BABYLON.Tools.ToRadians(90);
    var xR = { x: 0, y: 0, z: 0 };
    var yR = { x: 0, y: 0, z: deg };
    var zR = { x: 0, y: deg, z: 0 };

    var textSize = 1;
    var offset = 0.25;

    var xText = createText("X " + (bbv[5].x - bbv[3].x).toFixed(2) + "m", meshPosCenter.x, -(meshSize.y + offset), -bbv[3].z, textSize, xR, scene);
    var yText = createText("Y " + (bbv[5].y - bbv[2].y).toFixed(2) + "m", -meshSize.x + offset, meshPosCenter.y, -bbv[5].z, textSize, yR, scene);
    var zText = createText("Z " + (bbv[6].z - bbv[3].z).toFixed(2) + "m", bbv[3].x, -(meshSize.y + offset), meshPosCenter.z, textSize, zR, scene);

    scene.registerBeforeRender(() => {
      xText.billboardMode = BABYLON.Mesh.BILLBOARDMODE_ALL;
      yText.billboardMode = BABYLON.Mesh.BILLBOARDMODE_ALL;
      zText.billboardMode = BABYLON.Mesh.BILLBOARDMODE_ALL;
    });
  }

  var createText = function (text, posX, posY, posZ, size, rotation) {
    var outputplane = BABYLON.MeshBuilder.CreatePlane("outputplane", { size: Math.max(size, size, size) }, scene, false);

    outputplane.material = new BABYLON.StandardMaterial("outputplane", scene);
    outputplane.position = new BABYLON.Vector3(posX, posY, posZ);
    // outputplane.rotation = rotation;
    outputplane.renderingGroupId = 1;
    outputplane.scaling.x = -1;

    const textureSize = 512;

    var mat = new BABYLON.StandardMaterial("outputplane", scene);
    var dynTex = new BABYLON.DynamicTexture("dynamic texture", textureSize, scene, true);

    mat.diffuseTexture = dynTex;
    mat.specularColor = new BABYLON.Color3(0, 0, 0);
    mat.emissiveColor = new BABYLON.Color3(1, 1, 1);
    mat.backFaceCulling = false;
    dynTex.hasAlpha = true;
    outputplane.material = mat;

    var ctx = dynTex.getContext();
    ctx.clearRect(0, 0, textureSize, textureSize);

    const fontSize = 100;
    const font = `bold ${fontSize}px verdana`;
    const centerX = textureSize / 2;
    const centerY = 250;
    const outlineSize = 6;

    ctx.font = font;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    ctx.fillStyle = "#000";
    for (let dx = -outlineSize; dx <= outlineSize; dx++) {
      for (let dy = -outlineSize; dy <= outlineSize; dy++) {
        if (dx !== 0 || dy !== 0) {
          ctx.fillText(text, centerX + dx, centerY + dy);
        }
      }
    }

    ctx.fillStyle = "#fff";
    ctx.fillText(text, centerX, centerY);

    dynTex.update();

    return outputplane;
  };

  setBoundingText(box);

  return scene;
}
